using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.SceneManagement;using UnityEngine.Playables;using UnityEngine.Animations;using Sandbox.CharacterSystem;
public static class RenderClothingUnity {
 public static object Run(){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Edit Mode required");var scene=EditorSceneManager.NewPreviewScene();GameObject root=null;Material skin=null,shirt=null;try{
 root=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/_Sandbox/Characters/Ethan_V2/Ethan_V2.prefab"),scene);root.SetActive(true);root.transform.SetPositionAndRotation(Vector3.zero,Quaternion.identity);root.transform.localScale=Vector3.one;
 skin=new Material(Shader.Find("Universal Render Pipeline/Unlit"));skin.SetColor("_BaseColor",new Color(.65f,.43f,.3f));shirt=new Material(skin);shirt.SetColor("_BaseColor",new Color(.15f,.19f,.23f));
 foreach(var r in root.GetComponentsInChildren<Renderer>(true)){r.gameObject.layer=30;r.enabled=r.name=="BAKED_body_lod0_mesh"||r.name=="BAKED_Outfits_LOD0";if(r.enabled)r.sharedMaterials=Enumerable.Repeat(r.name=="BAKED_Outfits_LOD0"?shirt:skin,r.sharedMaterials.Length).ToArray();}
 var cameraObject=new GameObject("Clothing preview camera");SceneManager.MoveGameObjectToScene(cameraObject,scene);var camera=cameraObject.AddComponent<Camera>();camera.scene=scene;camera.cullingMask=1<<30;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.8f,.8f,.8f);camera.orthographic=true;camera.orthographicSize=.65f;camera.transform.position=new Vector3(0,1.25f,3);camera.transform.LookAt(new Vector3(0,1.25f,0));
 var defs=AssetDatabase.FindAssets("t:AnimationDefinition",new[]{"Assets/_Sandbox"}).Select(AssetDatabase.GUIDToAssetPath).Select(AssetDatabase.LoadAssetAtPath<AnimationDefinition>).Where(d=>d&&d.Clip&&d.Clip.isHumanMotion&&(d.name=="Idle"||d.name=="Thinking"||d.name=="Waving")).ToArray();
 var animator=root.GetComponentInChildren<AnimationModule>(true).Animator;var bridge=root.GetComponent<CharacterSkeletonPoseBridge>();Directory.CreateDirectory("Data/EthanV2/ClothingRepair/UnityRenders");
 foreach(var d in defs){var graph=PlayableGraph.Create("Disposable rendered clothing check");try{graph.SetTimeUpdateMode(DirectorUpdateMode.Manual);var p=AnimationClipPlayable.Create(graph,d.Clip);p.SetApplyFootIK(false);var output=AnimationPlayableOutput.Create(graph,"pose",animator);output.SetSourcePlayable(p);graph.Play();p.SetTime(d.Clip.length*.5);graph.Evaluate(0);bridge.ApplyPose();var rt=RenderTexture.GetTemporary(700,900,24);try{camera.targetTexture=rt;camera.Render();var previous=RenderTexture.active;RenderTexture.active=rt;var texture=new Texture2D(700,900,TextureFormat.RGB24,false);texture.ReadPixels(new Rect(0,0,700,900),0,0);texture.Apply();RenderTexture.active=previous;File.WriteAllBytes("Data/EthanV2/ClothingRepair/UnityRenders/"+d.name+".png",texture.EncodeToPNG());UnityEngine.Object.DestroyImmediate(texture);}finally{camera.targetTexture=null;RenderTexture.ReleaseTemporary(rt);}}finally{graph.Destroy();}}
 return new{poses=defs.Select(d=>d.name).ToArray()};
 }finally{if(skin)UnityEngine.Object.DestroyImmediate(skin);if(shirt)UnityEngine.Object.DestroyImmediate(shirt);EditorSceneManager.ClosePreviewScene(scene);}}
}
